/* COMPACT STATS (STYLE 4 MULTI-COLOR SOLID PILLS) */
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px;margin-bottom:12px}
.stat-card{
