}

/* CARDS, FORMS & TABLES */
.card{
  background:#ffffff;border:1px solid #e2e8f0;border-radius:14px;
  box-shadow:0 2px 8px rgba(15,23,42,.04);margin-bottom:12px;overflow:hidden;
}
.card-head{
  padding:10px 13px;border-bottom:1px solid #f1f5f9;background:#ffffff;
