}
.code-editor-box::selection{background:#2563eb;color:#ffffff}

/* ── FLOATING BOXED ICON BOTTOM DOCK (STYLE 4 MULTI-COLOR SOLID PILLS) ── */
.mob-dock{
  position:fixed;bottom:8px;left:10px;right:10px;height:56px;max-width:500px;margin:0 auto;
  background:#ffffff;border:1px solid #e2e8f0;border-radius:16px;z-index:120;
  display:grid;grid-template-columns:repeat(5,1fr);padding:4px;gap:4px;
  box-shadow:0 8px 24px rgba(15,23,42,.08);
}
.dock-btn{
  border:none;background:transparent;border-radius:11px;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:2px;font-size:9px;font-weight:700;color:var(--muted);
  font-family:inherit;cursor:pointer;transition:all .18s cubic-bezier(.34,1.56,.64,1);
